469	    /**
470	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
471	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
472	     * that is stored, returned and used for every value derived from it.
473	     *
474	     * @param date the effective registration date (supplied or defaulted)
475	     * @return the same date when it is a weekday, otherwise the next Monday
476	     */
477	    private LocalDate rollToBusinessDay(LocalDate date) {
478	        DayOfWeek dayOfWeek = date.getDayOfWeek();
479	        if (dayOfWeek == DayOfWeek.SATURDAY) {
480	            return date.plusDays(2);
481	        }
482	        if (dayOfWeek == DayOfWeek.SUNDAY) {
483	            return date.plusDays(1);
484	        }
485	        return date;
486	    }
